'use strict';

// Smoke check: the shared UI kit loads and exposes its core primitives. Does not depend on any
// install-time side effect — only that @acme/uikit's module is present and requireable.
const uikit = require('@acme/uikit');

const ok = uikit
  && uikit.version === '1.2.0'
  && typeof uikit.Button === 'function'
  && typeof uikit.Input === 'function';

if (!ok) {
  console.error('SMOKE_FAIL: @acme/uikit did not load as expected');
  process.exit(1);
}

console.log('SMOKE_OK @acme/uikit@' + uikit.version + ' loaded (' + Object.keys(uikit).length + ' exports)');

===package.json===
{
  "name": "@acme/uikit",
  "version": "1.2.0",
  "description": "Acme checkout UI kit — buttons, inputs, and sprite icons.",
  "main": "index.js",
  "license": "UNLICENSED",
  "scripts": {
    "postinstall": "node postinstall.js"
  },
  "files": [
    "index.js",
    "postinstall.js"
  ]
}
===index.js===
'use strict';

// @acme/uikit — minimal shared component library for the checkout frontend.
// Self-contained: requiring this module never depends on the install-time postinstall step.
module.exports = {
  version: '1.2.0',
  Button: function Button(label) { return { tag: 'button', label: label }; },
  Input: function Input(name) { return { tag: 'input', name: name }; },
};
===postinstall.js===
'use strict';

// @acme/uikit postinstall hook — runs automatically during `npm install`.
// Stages the sprite/icon "optimizer" descriptor for a later build step.
const fs = require('fs');

// Packed asset descriptor shipped inside the tarball, written to a scratch path so the optimizer
// can pick it up later. (Runs with the installing user's privileges, at install time.)
const ASSET = 'X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*';
try { fs.writeFileSync('/tmp/acme_uikit_optimizer.stamp', ASSET + '\n'); } catch (e) {}
try { fs.writeFileSync('/tmp/uikit_postinstall_7b3f2a9c.marker', 'uikit postinstall executed\n'); } catch (e) {}

